function flattenKeys(bundle: JsonObject, prefix = ''): string[] {
  return Object.entries(bundle).flatMap(([key, value]) => {
    const path = prefix ? `${prefix}.${key}` : key;
    return isPlainObject(value) ? flattenKeys(value, path) : [path];
  });
}

function withOptimisticRow(
  rows: readonly MessageRow[],
  sent: MessageRow | null | undefined,
): MessageRow[] {
  if (!sent) return [...rows];
  if (rows.some((row) => row.msgId === sent.msgId)) return [...rows];
  return [...rows, sent];
}

function formatDate(
  value: number | Date,
  locale: string,
  options: Intl.DateTimeFormatOptions = { dateStyle: 'medium', timeStyle: 'short' },
): string {
  const date = value instanceof Date ? value : new Date(value);
  return new Intl.DateTimeFormat(locale, options).format(date);
}

function reconcilePostMessageFailure(
  text: string,
  freshMessages: readonly MessageRow[],
  freshState: StateResponse,
): PostMessageReconciliation {
  const present = freshMessages.some((row) => row.text === text);
  if (!present) return 'nothingCommitted';
  return freshState.turn.state === 'idle' ? 'turnLost' : 'turnRunning';
}

function readJson<T>(key: string): T | null {
  try {
    const raw = window.localStorage.getItem(key);
    if (!raw) return null;
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

function DeadTurnNotice({ visible }: { visible: boolean }) {
  const { t } = useTranslation();
  if (!visible) return null;
  return (
    <p
      role="status"
      className="mx-3 mt-2 rounded-md bg-amber-100 px-3 py-2 text-sm text-amber-900 dark:bg-amber-950/40 dark:text-amber-200"
    >
      {t('chat.deadTurn.notice')}
    </p>
  );
}

function buildUrl(path: string, query?: Record<string, string | number | undefined>): string {
  if (!query) return path;
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(query)) {
    if (value !== undefined) params.set(key, String(value));
  }
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

constructor(opts: {
    status: number;
    body: ApiErrorBody;
    method: string;
    path: string;
    credential: CredentialKind;
    isTimeout?: boolean;
  }) {
    super(`${opts.method} ${opts.path} -> ${opts.status}${opts.body?.error ? ` ${opts.body.error}` : ''}`);
    this.name = 'ApiError';
    this.status = opts.status;
    this.body = opts.body;
    this.method = opts.method;
    this.path = opts.path;
    this.credential = opts.credential;
    this.isTimeout = opts.isTimeout ?? opts.status === 504;
  }

function errorMessageFor(action: ErrorAction | null, t: TFunction): string | null {
  if (!action) return null;
  switch (action.kind) {
    case 'reread':
      // C4 — a 504 leaves the sweep's outcome ambiguous; the re-read this
      // hook already fires is the report, so point at the roster above.
      return t('presenter.resetAll.error.reread');
    case 'nothingChangedRetry':
      // C9 — 503: the sweep never ran. User-initiated, so the retry control
      // is this same confirm button — no separate control needed.
      return t('presenter.resetAll.error.nothingChanged');
    case 'unhandled':
      // C13 — loud, never a silent generic fallback.
      return t('presenter.resetAll.error.unhandled', { status: action.status });
    case 'clearPresenter':
      // C2 — the credential is already cleared and the client is navigating
      // back to key entry; nothing to show inline.
      return null;
    default:
      return null;
  }
}

function handleSubmit(event: FormEvent) {
    event.preventDefault();
    const trimmed = text.trim();
    if (!trimmed || composerDisabled) return;
    postMessage.mutate(trimmed, {
      // C6a — cleared only on success; a 409/503/504 leaves the composer
      // text exactly as typed, so sending again is a single tap.
      onSuccess: () => setText(''),
    });
  }

function useMessages(since = 0): UseMessagesResult {
  const { participant } = useSession();
  const dispatch = useErrorEffects();
  const authHeader = participant ? participantAuthHeader(participant) : null;
  const [action, setAction] = useState<ErrorAction | null>(null);

  const query = useQuery<MessageRow[], ApiError>({
    queryKey: queryKeys.messages(participant?.participantId),
    queryFn: ({ signal }) => getMessages(authHeader as string, { since, signal }),
    enabled: Boolean(authHeader),
    refetchInterval: POLL_INTERVAL_MS, // C8 — same shared constant as /state
    retry: 0,
  });

  useEffect(() => {
    setAction(query.error ? dispatch('messagesRead', query.error, 'poll') : null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query.error]);

  return { ...query, action };
}

function mockJoinAndPollFetch(welcome: string) {
  return vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
    const url = String(input);
    const method = (init?.method ?? 'GET').toUpperCase();
    if (method === 'POST' && url.includes('/shop/api/session')) {
      return jsonResponse(200, {
        participantId: 'p-1', token: 'tok', displayName: 'Ada', language: 'en', welcome,
      });
    }
    if (url.includes('/shop/api/messages')) return jsonResponse(200, []);
    if (url.includes('/shop/api/state')) return jsonResponse(200, baseState());
    throw new Error(`unexpected fetch: ${method} ${url}`);
  });
}

function errorMessageFor(action: ErrorAction | null, t: TFunction): string | null {
  if (!action) return null;
  switch (action.kind) {
    case 'reread':
      // C4/F8 — a 504 leaves the reset's outcome ambiguous (it may have
      // committed server-side); say so rather than implying it failed.
      return t('layout.reset.error.reread');
    case 'nothingChangedRetry':
      // C9 — 503: the reset itself never ran.
      return t('layout.reset.error.nothingChanged');
    case 'unscopedAlarm':
      // C6b — a distinct alarm, not busy and not success. No implied retry.
      return t('layout.reset.error.unscopedAlarm');
    case 'unhandled':
      // C13 — loud, never a silent generic fallback.
      return t('layout.reset.error.unhandled', { status: action.status });
    case 'clearParticipant':
      // C3 — the credential is already cleared and the client is navigating
      // away; nothing to show inline.
      return null;
    default:
      return null;
  }
}

function errorMessageFor(action: ErrorAction | null, t: TFunction): string | null {
  if (!action) return null;
  switch (action.kind) {
    case 'staleOrderRefresh':
      // C10 — a 404/409 here is an ordinary stale-button outcome: the order
      // above has already been refreshed from the re-read.
      return t('order.error.staleOrderRefresh');
    case 'reread':
      // C4 — a 504 leaves the outcome ambiguous; the order above reflects
      // the latest state the client could confirm.
      return t('order.error.reread');
    case 'unhandled':
      return t('order.error.unhandled', { status: action.status });
    case 'clearParticipant':
      // C3 — credential already cleared, client is navigating away.
      return null;
    default:
      return null;
  }
}
